mapper.insert:

    SELECT fn_get_dynamic_seq('utb_biz_info')


INSERT INTO utb_biz_info (
    biz_info_seq,
    office_seq,
    corp_code,
    ceo_name,
    biz_reg_no,
    biz_workplace_no,
    biz_corp_name,
    biz_addr,
    biz_addr_detail,
    biz_fax_no,
    biz_tel_no,
    biz_post_no,
    biz_type,
    biz_kind,
    reg_discount_code,
    year_discount_code,
    discount_closing_date,
    reduction_reason,
    reduction_issue_date,

    biz_contact_name,
    biz_dept_name,
    biz_email,
    create_user, create_at, del_yn, note
) VALUES (
#{bizInfoSeq}
    , #{officeSeq}
    , #{corpCode}
    , #{ceoName}
    , #{bizRegNo}
    , #{bizWorkplaceNo}
    , #{bizCorpName}
    , #{bizAddr}
    , #{bizAddrDetail}
    , #{bizFaxNo}
    , #{bizTelNo}
    , #{bizPostNo}
    , #{bizType}
    , #{bizKind}
    , #{regDiscountCode}
    , #{yearDiscountCode}
    , NULLIF(#{discountClosingDate}, '')::timestamptz
    , #{reductionReason}
    , NULLIF(#{reductionIssueDate}, '')::timestamptz
    , #{bizContactName}
    , #{bizDeptName}
    , #{bizEmail}
    , #{createUser}
    , CURRENT_TIMESTAMP
    , 'N'
    , #{note}
         )
